const belenPersonalScene=STORIES[5].chapters[3].narrative.find(n=>n.text.startsWith('Belén se acercó a una ventana'));
const belenInvitation=STORIES[5].chapters[3].narrative.find(n=>n.text.includes('La media sonrisa de sus labios bordó'));
STORIES[5].chapters[3].narrative=STORIES[5].chapters[3].narrative.filter(n=>n!==belenPersonalScene&&n!==belenInvitation);
STORIES.forEach((s,i)=>s.chapters.forEach((c,j)=>{
 if(j===0)return;
 c.routeScenes=slot=>{
  const first=slot.choices?.[0];if(![0,1,2].includes(first))return [];
  const main=routeThreads[i][j-1][first].map(([speaker,text])=>({speaker,text}));
  if(j>=2){const previous=slot.choices?.[j-1];if([0,1,2].includes(previous)){const [speaker,text]=laterChoiceEchoes[i][j-2][previous];main.push({speaker,text});}}
  if(i===5&&j===3){
   if(slot.choices?.[1]!==2){if(belenPersonalScene)main.push(belenPersonalScene);if(belenInvitation)main.push(belenInvitation);}
   else main.push({speaker:'Belén · ♥',text:'Belén dejó su plan sobre la mesa del acta, a una distancia que no era una invitación personal. «Voy a responder por el borrador y voy a ayudar a abrir las puertas que pueda», dijo. «Eso no significa que volvamos al vínculo que teníamos antes de que me atribuyeras toda la infección». No te pidió un gesto para desbloquear su cercanía. Conservó el corazón verde en su propia solapa y eligió trabajar junto a Marea mientras vos recibías las tareas de la última página.'});
  }
  return main;
 };
}));

const focusResolutions=[
 'El Índice bloqueó el permiso de reescritura del sello que Pipo había guardado en la bufanda. No lo castigó por tener miedo ni lo convirtió en alguien incapaz de elegir: desde ese momento sus palabras ya no pudieron alterar otras voces mediante aquella guía. El robo de Teo y las condiciones que impusieron a Nilo siguieron teniendo las consecuencias del recorrido.',
 'El Índice retiró a la ficha de la mesa el permiso de transformar una orden de Rosa en letras ajenas. La niña conservó sus recuerdos y el derecho a querer compañía. El bloqueo del foco no abrió por sí solo habitaciones, devolvió contratos ni decidió a quién perdonar: esas consecuencias dependieron de lo que hicieron con la casa.',
 'El Índice dejó sin efecto el sello del libro de discursos de León. Impidió que su necesidad de obediencia reescribiera fuentes, no que pudiera equivocarse ni que siguiera teniendo responsabilidades como gobernante. La falsificación del Maestro, los fondos y las represalias conservaron sus propios expedientes.',
 'El Índice bloqueó el sello de la hoja que Nora había aceptado entre instrucciones de ayuda. Eso detuvo la alteración mágica, no la infraestructura capaz de difundir exclusiones ordinarias. Separar los canales, restituir accesos y proteger la autonomía de Eco siguió dependiendo de las decisiones registradas.',
 'El Índice retiró al modelo de tratado el permiso de torcer una voz cuando Jhenn intentaba imponer la suya. La escribiente no perdió por eso su capacidad de trabajar ni obtuvo una absolución. Los mandatos ejercidos sin permiso, las acusaciones y las garantías del valle mantuvieron sus efectos.',
 'El registro preservó el origen de la orden bajo custodias distintas. Identificar a Áster no ejecutó por sí solo una reparación ni lo convirtió en la única persona que hubiera elegido algo. El archivo conservó el cambio de permisos y el cierre que autorizaste, incluidos los resultados adversos.'
];
