window.registerWorld=function(world){
 const fail=detail=>{throw Error('Paquete de mundo inválido: '+detail);};
 const text=v=>typeof v==='string'&&v.trim().length>0;
 const list3=v=>Array.isArray(v)&&v.length===3&&v.every(text);
 if(!world||typeof world!=='object'||!text(world.id)||!(/^[a-z][a-z0-9-]{0,63}$/).test(world.id)||['__proto__','prototype','constructor'].includes(world.id))fail('identificador seguro requerido');
 if(STORIES.some(s=>s.id===world.id))fail('identificador duplicado');
 for(const key of ['title','subtitle','level','focus','genre','lead','companion','description'])if(!text(world[key]))fail('falta metadata '+key);
 if(!Array.isArray(world.chapters)||world.chapters.length<1)fail('al menos una sección completa');
 world.chapters.forEach((c,index)=>{
  if(!c||!text(c.title)||!text(c.location)||!text(c.boss)||!text(c.closing))fail('título, lugar, rival o cierre en sección '+index);
  if(!Array.isArray(c.narrative)||!c.narrative.length||!c.narrative.every(n=>typeof n==='string'?text(n):n&&text(n.text)))fail('narrativa de sección '+index);
  if(!Array.isArray(c.docs)||c.docs.length!==3||!c.docs.every(d=>d&&text(d.title)&&text(d.text)&&text(d.clue)))fail('tres documentos completos en sección '+index);
  if(!c.decision||!text(c.decision.question)||!list3(c.decision.options)||!list3(c.decision.results)||!list3(c.decision.echoes))fail('decisión con tres resultados y ecos en sección '+index);
  if(!Array.isArray(c.rounds)||c.rounds.length!==3||!c.rounds.every(r=>r&&text(r.status)&&list3(r.options)&&Number.isInteger(r.answer)&&r.answer>=0&&r.answer<3&&text(r.why)&&text(r.wrong)&&Number.isInteger(r.evidence)&&r.evidence>=0&&r.evidence<3))fail('tres fases de duelo completas en sección '+index);
  if(!list3(c.timeline))fail('secuencia de tres hechos en sección '+index);
  const repair=c.repair||world.repair;if(!list3(repair))fail('enmienda de sección '+index);
 });
 const count=world.chapters.length*3;
 const pair=v=>Array.isArray(v)&&v.length===2&&v[0]!==v[1]&&v.every(n=>Number.isInteger(n)&&n>=0&&n<count);
 const m=world.mystery;if(!m||!list3(m.suspects)||!Number.isInteger(m.answer)||m.answer<0||m.answer>2||!pair(m.evidence)||!text(m.why))fail('hipótesis con sospechosos y dos fuentes válidas');
 if(m.acceptedEvidence!==undefined&&(!Array.isArray(m.acceptedEvidence)||!m.acceptedEvidence.length||!m.acceptedEvidence.every(pair)))fail('pares de evidencia alternativa');
 if(!Array.isArray(world.synthesis)||world.synthesis.length!==3||!world.synthesis.every(q=>q&&text(q.question)&&list3(q.options)&&Number.isInteger(q.answer)&&q.answer>=0&&q.answer<3&&text(q.explanation)))fail('tres conclusiones respaldadas');
 for(const key of ['true','good','goodCost','mixed','dark','darkControl','darkLoss'])if(!Array.isArray(world.endings?.[key])||world.endings[key].length!==2||!world.endings[key].every(text))fail('desenlace '+key);
 if(world.requires!==undefined&&(!Array.isArray(world.requires)||!world.requires.every(id=>text(id)&&id!==world.id&&STORIES.some(s=>s.id===id))))fail('requisitos registrados y sin autorreferencia');
 world.pack??='expansion';world.requires??=[];m.acceptedEvidence??=[m.evidence.slice()];m.question??='¿Qué hipótesis sostienen las fuentes?';m.role??='caso del mundo';STORIES.push(world);
};
